 type_id TEXT, type_version INTEGER,
 case_number TEXT, court TEXT, insurance_limit_cents INTEGER CHECK(insurance_limit_cents IS NULL OR insurance_limit_cents>=0),
 fee_arrangement TEXT CHECK(fee_arrangement IS NULL OR fee_arrangement IN ('hourly','flat_fee','contingency','hybrid','pro_bono')),
 fee_terms TEXT, custom TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(custom)),
 revision TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL,
 FOREIGN KEY(type_id,type_version) REFERENCES s_matter_type_versions(type_id,version)
);
CREATE INDEX s_matter_case_number ON s_matter_fields(case_number);
CREATE TABLE s_matter_field_events (
 id TEXT PRIMARY KEY, matter_id TEXT NOT NULL REFERENCES s_matters(id),
 kind TEXT NOT NULL CHECK(kind IN ('saved','adopted','imported')),
 detail TEXT NOT NULL CHECK(json_valid(detail)), actor TEXT NOT NULL, at TEXT NOT NULL
);
CREATE INDEX s_matter_field_history ON s_matter_field_events(matter_id,at,id);
CREATE TRIGGER s_matter_field_event_immutable_update BEFORE UPDATE ON s_matter_field_events
 BEGIN SELECT RAISE(ABORT,'immutable matter field event'); END;
CREATE TRIGGER s_matter_field_event_immutable_delete BEFORE DELETE ON s_matter_field_events
 BEGIN SELECT RAISE(ABORT,'immutable matter field event'); END;

-- TIME-001: per-person timers, weekly timesheet drafts and idempotent posting.
-- Existing entries stay billable; posted drafts carry their activity class and UTBMS codes.
ALTER TABLE s_entries ADD COLUMN billable INTEGER NOT NULL DEFAULT 1 CHECK(billable IN (0,1));
ALTER TABLE s_entries ADD COLUMN utbms_task TEXT;
ALTER TABLE s_entries ADD COLUMN utbms_activity TEXT;
CREATE TABLE s_timers (
 id TEXT PRIMARY KEY, owner_email TEXT NOT NULL, matter_id TEXT NOT NULL REFERENCES s_matters(id),
 description TEXT NOT NULL, billable INTEGER NOT NULL CHECK(billable IN (0,1)),
 status TEXT NOT NULL CHECK(status IN ('running','paused','stopped')),
 revision TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX s_timers_owner ON s_timers(owner_email,status);
-- At most one running timer per person: a second one can never overlap unnoticed.
CREATE UNIQUE INDEX s_timers_one_running ON s_timers(owner_email) WHERE status='running';
CREATE TABLE s_timer_intervals (
 id TEXT PRIMARY KEY, timer_id TEXT NOT NULL REFERENCES s_timers(id), owner_email TEXT NOT NULL,
 started_at TEXT NOT NULL, ended_at TEXT, started_channel TEXT NOT NULL, ended_reason TEXT
);
CREATE UNIQUE INDEX s_timer_open_interval ON s_timer_intervals(owner_email) WHERE ended_at IS NULL;
CREATE TABLE s_time_drafts (
 id TEXT PRIMARY KEY, owner_email TEXT NOT NULL, matter_id TEXT NOT NULL REFERENCES s_matters(id),
 date TEXT NOT NULL, minutes INTEGER NOT NULL CHECK(minutes BETWEEN 1 AND 1440),
 rate_cents INTEGER NOT NULL CHECK(rate_cents BETWEEN 0 AND 100000000),
 description TEXT NOT NULL, billable INTEGER NOT NULL CHECK(billable IN (0,1)),
 utbms_task TEXT, utbms_activity TEXT,
 source TEXT NOT NULL CHECK(source IN ('timer','timesheet')), interval_id TEXT UNIQUE REFERENCES s_timer_intervals(id),
 status TEXT NOT NULL CHECK(status IN ('draft','rejected','posted')), entry_id TEXT UNIQUE REFERENCES s_entries(id),
 revision TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX s_time_drafts_day ON s_time_drafts(owner_email,date,status);

-- TIME-003: append-only fee-agreement rate rules, versioned matter budgets and
-- once-per-level budget alerts. Recorded entries keep the price resolved when recorded.
CREATE TABLE s_rate_rules (
 id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('firm','client','matter')), scope_key TEXT NOT NULL,
 timekeeper_email TEXT, utbms_task TEXT, effective_from TEXT NOT NULL,
 rate_cents INTEGER NOT NULL CHECK(rate_cents BETWEEN 0 AND 100000000),
 increment_minutes INTEGER NOT NULL CHECK(increment_minutes BETWEEN 1 AND 60),
 discount_bps INTEGER NOT NULL CHECK(discount_bps BETWEEN 0 AND 10000), billable INTEGER NOT NULL CHECK(billable IN (0,1)),
 note TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE UNIQUE INDEX s_rate_rule_key ON s_rate_rules(scope,scope_key,COALESCE(timekeeper_email,''),COALESCE(utbms_task,''),effective_from);
CREATE TRIGGER s_rate_rules_immutable_update BEFORE UPDATE ON s_rate_rules BEGIN SELECT RAISE(ABORT,'constraint: rate rules are versioned history'); END;
CREATE TRIGGER s_rate_rules_immutable_delete BEFORE DELETE ON s_rate_rules BEGIN SELECT RAISE(ABORT,'constraint: rate rules are versioned history'); END;
CREATE TABLE s_matter_budgets (
 id TEXT PRIMARY KEY, matter_id TEXT NOT NULL REFERENCES s_matters(id), version INTEGER NOT NULL CHECK(version>0),
 cents INTEGER NOT NULL CHECK(cents BETWEEN 1 AND 1000000000000), alert_percent INTEGER NOT NULL CHECK(alert_percent BETWEEN 1 AND 100),
 note TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(matter_id,version)
);
CREATE TRIGGER s_matter_budgets_immutable_update BEFORE UPDATE ON s_matter_budgets BEGIN SELECT RAISE(ABORT,'constraint: budgets are versioned history'); END;
CREATE TRIGGER s_matter_budgets_immutable_delete BEFORE DELETE ON s_matter_budgets BEGIN SELECT RAISE(ABORT,'constraint: budgets are versioned history'); END;
CREATE TABLE s_budget_alerts (
 id TEXT PRIMARY KEY, budget_id TEXT NOT NULL REFERENCES s_matter_budgets(id), matter_id TEXT NOT NULL REFERENCES s_matters(id),
 level TEXT NOT NULL CHECK(level IN ('threshold','exceeded')), used_cents INTEGER NOT NULL, budget_cents INTEGER NOT NULL,
 entry_id TEXT REFERENCES s_entries(id), at TEXT NOT NULL, UNIQUE(budget_id,level)
);
CREATE TRIGGER s_budget_alerts_immutable_update BEFORE UPDATE ON s_budget_alerts BEGIN SELECT RAISE(ABORT,'constraint: budget alerts are history'); END;
CREATE TRIGGER s_budget_alerts_immutable_delete BEFORE DELETE ON s_budget_alerts BEGIN SELECT RAISE(ABORT,'constraint: budget alerts are history'); END;
-- Entries record how their charge was priced; earlier entries keep NULL (exact as entered).
ALTER TABLE s_entries ADD COLUMN billed_minutes INTEGER;
ALTER TABLE s_entries ADD COLUMN discount_bps INTEGER;
ALTER TABLE s_entries ADD COLUMN rate_rule_id TEXT;
ALTER TABLE s_entries ADD COLUMN rate_source TEXT CHECK(rate_source IS NULL OR rate_source IN ('entry','rule','firm-default'));
-- A draft with an explicit rate keeps it; other drafts are priced by the fee agreement.
ALTER TABLE s_time_drafts ADD COLUMN rate_source TEXT NOT NULL DEFAULT 'schedule' CHECK(rate_source IN ('entry','schedule'));

-- MATTER-004: versioned practice workflows, reviewed runs and once-only generated steps.
CREATE TABLE s_workflows (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, trigger TEXT NOT NULL CHECK(trigger IN ('manual','opening','stage')),
 trigger_stage_id TEXT REFERENCES s_matter_stages(id), current_version INTEGER NOT NULL CHECK(current_version>0),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, CHECK((trigger='stage')=(trigger_stage_id IS NOT NULL))
);
CREATE UNIQUE INDEX s_workflow_name ON s_workflows(lower(name));
CREATE TRIGGER s_workflow_fixed BEFORE UPDATE ON s_workflows WHEN NEW.id IS NOT OLD.id OR NEW.name IS NOT OLD.name OR NEW.trigger IS NOT OLD.trigger OR NEW.trigger_stage_id IS NOT OLD.trigger_stage_id OR NEW.current_version<>OLD.current_version+1
 BEGIN SELECT RAISE(ABORT,'constraint: workflows only gain versions'); END;
CREATE TRIGGER s_workflow_delete BEFORE DELETE ON s_workflows BEGIN SELECT RAISE(ABORT,'constraint: workflows are history'); END;
CREATE TABLE s_workflow_versions (
 workflow_id TEXT NOT NULL REFERENCES s_workflows(id), version INTEGER NOT NULL CHECK(version>0),
 steps TEXT NOT NULL CHECK(json_valid(steps) AND json_type(steps)='array'), note TEXT NOT NULL,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(workflow_id,version)
);
CREATE TRIGGER s_workflow_version_update BEFORE UPDATE ON s_workflow_versions BEGIN SELECT RAISE(ABORT,'constraint: workflow versions are immutable'); END;
CREATE TRIGGER s_workflow_version_delete BEFORE DELETE ON s_workflow_versions BEGIN SELECT RAISE(ABORT,'constraint: workflow versions are immutable'); END;
CREATE TABLE s_workflow_runs (
 id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES s_workflows(id), matter_id TEXT NOT NULL REFERENCES s_matters(id),
 version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','active','stopped')),
 source TEXT NOT NULL CHECK(source IN ('manual','opening','stage')), source_id TEXT,
 approved_steps TEXT NOT NULL CHECK(json_valid(approved_steps) AND json_type(approved_steps)='array'),
 revision TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX s_workflow_live_run ON s_workflow_runs(matter_id,workflow_id) WHERE status IN ('proposed','active');
CREATE TRIGGER s_workflow_run_delete BEFORE DELETE ON s_workflow_runs BEGIN SELECT RAISE(ABORT,'constraint: workflow runs are history'); END;
-- One generated record per run step: a restart or repeated approval creates nothing twice.
CREATE TABLE s_workflow_run_items (
 run_id TEXT NOT NULL REFERENCES s_workflow_runs(id), step_key TEXT NOT NULL, version INTEGER NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('task','appointment','document_request','draft_document')), item_id TEXT NOT NULL,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(run_id,step_key)
);
CREATE TRIGGER s_workflow_item_update BEFORE UPDATE ON s_workflow_run_items BEGIN SELECT RAISE(ABORT,'constraint: generated steps are history'); END;
CREATE TRIGGER s_workflow_item_delete BEFORE DELETE ON s_workflow_run_items BEGIN SELECT RAISE(ABORT,'constraint: generated steps are history'); END;
CREATE TABLE s_workflow_run_events (
 id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES s_workflow_runs(id), kind TEXT NOT NULL,
 detail TEXT NOT NULL CHECK(json_valid(detail)), actor TEXT NOT NULL, at TEXT NOT NULL
);
CREATE TRIGGER s_workflow_event_update BEFORE UPDATE ON s_workflow_run_events BEGIN SELECT RAISE(ABORT,'constraint: workflow history is append-only'); END;
CREATE TRIGGER s_workflow_event_delete BEFORE DELETE ON s_workflow_run_events BEGIN SELECT RAISE(ABORT,'constraint: workflow history is append-only'); END;
-- A document request is a recorded request for the client's documents; Satchel sends nothing.
CREATE TABLE s_document_requests (
 id TEXT PRIMARY KEY, matter_id TEXT NOT NULL REFERENCES s_matters(id), title TEXT NOT NULL, due_date TEXT,
 status TEXT NOT NULL CHECK(status IN ('open','received')), document_id TEXT REFERENCES s_documents(id),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, received_by TEXT, received_at TEXT,
 CHECK(status='open' OR document_id IS NOT NULL)
);
CREATE TRIGGER s_document_request_once BEFORE UPDATE ON s_document_requests WHEN OLD.status='received' OR NEW.matter_id IS NOT OLD.matter_id OR NEW.title IS NOT OLD.title OR NEW.created_at IS NOT OLD.created_at
 BEGIN SELECT RAISE(ABORT,'constraint: a received request is final'); END;
CREATE TRIGGER s_document_request_delete BEFORE DELETE ON s_document_requests BEGIN SELECT RAISE(ABORT,'constraint: document requests are history'); END;

-- INTAKE-002: prospective-client leads through firm-edited stages, with assignment,
-- qualification, referral source, consultation outcome, next action and append-only history.
CREATE TABLE s_lead_stages (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0),
 revision TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX s_lead_stage_name ON s_lead_stages(lower(name));
CREATE TABLE s_leads (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL,
 referral_source TEXT NOT NULL, stage_id TEXT REFERENCES s_lead_stages(id), assigned_email TEXT,
 qualification TEXT NOT NULL DEFAULT 'pending' CHECK(qualification IN ('pending','qualified','not_qualified')),
 consultation_outcome TEXT NOT NULL DEFAULT '', next_action TEXT NOT NULL DEFAULT '', next_action_date TEXT,
 status TEXT NOT NULL CHECK(status IN ('open','lost','converted','merged')), lost_reason TEXT, matter_id TEXT REFERENCES s_matters(id), merged_into TEXT REFERENCES s_leads(id),
 revision TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, last_activity_at TEXT NOT NULL,
 CHECK(status<>'lost' OR lost_reason IS NOT NULL), CHECK(status<>'converted' OR matter_id IS NOT NULL), CHECK(status<>'merged' OR merged_into IS NOT NULL)
);
CREATE UNIQUE INDEX s_leads_converted_matter ON s_leads(matter_id) WHERE status='converted';
CREATE INDEX s_leads_queue ON s_leads(assigned_email,status,next_action_date);
CREATE TRIGGER s_lead_delete BEFORE DELETE ON s_leads BEGIN SELECT RAISE(ABORT,'constraint: leads are history'); END;
CREATE TRIGGER s_lead_final BEFORE UPDATE ON s_leads WHEN OLD.status='merged' OR NEW.created_at IS NOT OLD.created_at OR NEW.created_by IS NOT OLD.created_by OR NEW.referral_source IS NOT OLD.referral_source
 BEGIN SELECT RAISE(ABORT,'constraint: a merged lead and lead provenance are final'); END;
CREATE TABLE s_lead_events (
 id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES s_leads(id), kind TEXT NOT NULL,
 detail TEXT NOT NULL CHECK(json_valid(detail)), actor TEXT NOT NULL, at TEXT NOT NULL
);
CREATE INDEX s_lead_history ON s_lead_events(lead_id,at,id);
CREATE TRIGGER s_lead_event_update BEFORE UPDATE ON s_lead_events BEGIN SELECT RAISE(ABORT,'constraint: lead history is append-only'); END;
CREATE TRIGGER s_lead_event_delete BEFORE DELETE ON s_lead_events BEGIN SELECT RAISE(ABORT,'constraint: lead history is append-only'); END;

-- INTAKE-001. Published revisions and original submissions remain immutable.
CREATE TABLE s_intake_forms (
 id TEXT PRIMARY KEY, revision TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0),
 published INTEGER NOT NULL CHECK(published IN(0,1)), assigned_email TEXT NOT NULL,
 snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE s_intake_form_versions (
 form_id TEXT NOT NULL REFERENCES s_intake_forms(id), version INTEGER NOT NULL,
 revision TEXT NOT NULL UNIQUE, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(form_id,version)
);
CREATE TABLE s_intake_submissions (
 id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES s_leads(id), form_id TEXT NOT NULL,
 form_version INTEGER NOT NULL, receipt TEXT NOT NULL UNIQUE, submitted_at TEXT NOT NULL,
 original_data TEXT NOT NULL CHECK(json_valid(original_data)),
 FOREIGN KEY(form_id,form_version) REFERENCES s_intake_form_versions(form_id,version)
);
CREATE INDEX s_intake_submissions_lead ON s_intake_submissions(lead_id,submitted_at);
CREATE TABLE s_intake_files (
 id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES s_intake_submissions(id),
 name TEXT NOT NULL, mime TEXT NOT NULL CHECK(mime IN('application/pdf','image/png','image/jpeg')),
 size INTEGER NOT NULL CHECK(size>0 AND size<=10485760), sha256 TEXT NOT NULL,
 object_key TEXT NOT NULL UNIQUE, scan_status TEXT NOT NULL DEFAULT 'not malware-scanned' CHECK(scan_status='not malware-scanned')
);
-- Ephemeral security data: explicitly excluded from portability archives.
CREATE TABLE s_intake_tokens (
 token_hash TEXT PRIMARY KEY, form_id TEXT NOT NULL REFERENCES s_intake_forms(id),
 revision TEXT NOT NULL, expires_at TEXT NOT NULL, submission_id TEXT REFERENCES s_intake_submissions(id)
);
CREATE INDEX s_intake_tokens_expiry ON s_intake_tokens(expires_at);
CREATE TABLE s_intake_rate_limits (
 form_id TEXT NOT NULL REFERENCES s_intake_forms(id), hour TEXT NOT NULL, ip_digest TEXT NOT NULL,
 accepted INTEGER NOT NULL CHECK(accepted BETWEEN 0 AND 10), expires_at TEXT NOT NULL,
 PRIMARY KEY(form_id,hour,ip_digest)
);
CREATE INDEX s_intake_rate_expiry ON s_intake_rate_limits(expires_at);
CREATE TRIGGER s_intake_version_update BEFORE UPDATE ON s_intake_form_versions BEGIN SELECT RAISE(ABORT,'constraint: intake versions are immutable'); END;
CREATE TRIGGER s_intake_version_delete BEFORE DELETE ON s_intake_form_versions BEGIN SELECT RAISE(ABORT,'constraint: intake versions are immutable'); END;
CREATE TRIGGER s_intake_submission_update BEFORE UPDATE ON s_intake_submissions BEGIN SELECT RAISE(ABORT,'constraint: original intake is immutable'); END;
CREATE TRIGGER s_intake_submission_delete BEFORE DELETE ON s_intake_submissions BEGIN SELECT RAISE(ABORT,'constraint: original intake is immutable'); END;
CREATE TRIGGER s_intake_file_update BEFORE UPDATE ON s_intake_files BEGIN SELECT RAISE(ABORT,'constraint: original intake files are immutable'); END;
CREATE TRIGGER s_intake_file_delete BEFORE DELETE ON s_intake_files BEGIN SELECT RAISE(ABORT,'constraint: original intake files are immutable'); END;
-- A durable staging reservation permits cleanup after a Worker dies during an R2 put.
CREATE TABLE s_intake_uploads (
 object_key TEXT PRIMARY KEY, expires_at TEXT NOT NULL
);

CREATE TABLE s_integrations(id TEXT PRIMARY KEY,label TEXT NOT NULL,owner_id TEXT NOT NULL,digest TEXT NOT NULL UNIQUE,scopes TEXT NOT NULL,matter_ids TEXT NOT NULL,endpoint TEXT,event_types TEXT NOT NULL,secret_sealed TEXT,enabled_at TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,paused INTEGER NOT NULL DEFAULT 0,failure_count INTEGER NOT NULL DEFAULT 0,generation INTEGER NOT NULL DEFAULT 1);
CREATE TABLE s_integration_requests(integration_id TEXT NOT NULL REFERENCES s_integrations(id),request_key TEXT NOT NULL,fingerprint TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(integration_id,request_key));
CREATE TABLE s_integration_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,matter_id TEXT,object_id TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE s_webhook_deliveries(integration_id TEXT NOT NULL REFERENCES s_integrations(id),event_id TEXT NOT NULL REFERENCES s_integration_events(id),status TEXT NOT NULL DEFAULT 'queued',claim TEXT,lease_until TEXT,PRIMARY KEY(integration_id,event_id));
CREATE TABLE s_webhook_attempts(sequence INTEGER PRIMARY KEY AUTOINCREMENT,integration_id TEXT NOT NULL,event_id TEXT NOT NULL,at TEXT NOT NULL,outcome TEXT NOT NULL,http_status INTEGER);
CREATE TRIGGER s_webhook_attempts_no_update BEFORE UPDATE ON s_webhook_attempts BEGIN SELECT RAISE(ABORT,'webhook journal is append-only'); END;
CREATE TRIGGER s_webhook_attempts_no_delete BEFORE DELETE ON s_webhook_attempts BEGIN SELECT RAISE(ABORT,'webhook journal is append-only'); END;
CREATE TRIGGER s_integration_events_no_update BEFORE UPDATE ON s_integration_events BEGIN SELECT RAISE(ABORT,'integration events are append-only'); END;
CREATE TRIGGER s_integration_events_no_delete BEFORE DELETE ON s_integration_events BEGIN SELECT RAISE(ABORT,'integration events are append-only'); END;
CREATE TRIGGER s_integration_matter_created AFTER INSERT ON s_matters BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'matter.created',NEW.id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_matter_updated AFTER UPDATE ON s_matters BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'matter.updated',NEW.id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_task_created AFTER INSERT ON s_tasks BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'task.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_task_updated AFTER UPDATE ON s_tasks BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'task.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_document_updated AFTER UPDATE ON s_documents WHEN NEW.current_version>0 BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'document.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_deadline_created AFTER INSERT ON s_deadlines BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'deadline.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_deadline_updated AFTER UPDATE ON s_deadlines BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'deadline.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_bill_created AFTER INSERT ON s_bills BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'finance.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_bill_updated AFTER UPDATE ON s_bills BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'finance.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_entry_created AFTER INSERT ON s_entries BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'finance.changed',NEW.matter_id,NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_trust_created AFTER INSERT ON s_trust_entries WHEN NEW.ledger_id IS NOT NULL BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'finance.changed',(SELECT matter_id FROM s_trust_ledgers WHERE id=NEW.ledger_id),NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER s_integration_proposal_decided AFTER UPDATE ON s_proposals WHEN NEW.status<>OLD.status BEGIN INSERT INTO s_integration_events(id,kind,matter_id,object_id,at) VALUES(lower(hex(randomblob(16))),'proposal.decided',COALESCE(json_extract(NEW.payload,'$.matterId'),CASE WHEN NEW.kind='matter' THEN NEW.result_id END),NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;

CREATE TABLE s_trust_checks(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,transaction_id TEXT NOT NULL UNIQUE REFERENCES s_trust_transactions(id),account_id TEXT NOT NULL REFERENCES s_trust_accounts(id),ledger_id TEXT REFERENCES s_trust_ledgers(id),check_number TEXT NOT NULL,revision TEXT NOT NULL,original_check_id TEXT UNIQUE REFERENCES s_trust_checks(id),reissue_reason TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(account_id,check_number));
CREATE TABLE s_trust_check_voids(check_id TEXT PRIMARY KEY REFERENCES s_trust_checks(id),reversal_id TEXT NOT NULL UNIQUE REFERENCES s_trust_journal_reversals(id));
CREATE TABLE s_trust_deposit_slips(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,account_id TEXT NOT NULL REFERENCES s_trust_accounts(id),slip_number TEXT NOT NULL,bank_reference TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(account_id,slip_number));
CREATE TABLE s_trust_deposit_items(slip_id TEXT NOT NULL REFERENCES s_trust_deposit_slips(id),entry_id TEXT NOT NULL UNIQUE REFERENCES s_trust_entries(id),PRIMARY KEY(slip_id,entry_id));
CREATE TRIGGER s_trust_checks_no_update BEFORE UPDATE ON s_trust_checks BEGIN SELECT RAISE(ABORT,'numbered checks are immutable'); END;
CREATE TRIGGER s_trust_checks_no_delete BEFORE DELETE ON s_trust_checks BEGIN SELECT RAISE(ABORT,'check numbers are retained permanently'); END;
CREATE TRIGGER s_trust_check_voids_no_update BEFORE UPDATE ON s_trust_check_voids BEGIN SELECT RAISE(ABORT,'check void links are immutable'); END;
CREATE TRIGGER s_trust_check_voids_no_delete BEFORE DELETE ON s_trust_check_voids BEGIN SELECT RAISE(ABORT,'check void links are immutable'); END;
CREATE TRIGGER s_trust_deposit_slips_no_update BEFORE UPDATE ON s_trust_deposit_slips BEGIN SELECT RAISE(ABORT,'deposit records are immutable'); END;
CREATE TRIGGER s_trust_deposit_slips_no_delete BEFORE DELETE ON s_trust_deposit_slips BEGIN SELECT RAISE(ABORT,'deposit records are immutable'); END;
CREATE TRIGGER s_trust_deposit_items_no_update BEFORE UPDATE ON s_trust_deposit_items BEGIN SELECT RAISE(ABORT,'deposit sources are immutable'); END;
CREATE TRIGGER s_trust_deposit_items_no_delete BEFORE DELETE ON s_trust_deposit_items BEGIN SELECT RAISE(ABORT,'deposit sources are immutable'); END;
-- Clearance and void approval compete in the same database transaction, including
-- through the older journal/clearance doors. A stopped check cannot clear later.
CREATE TRIGGER s_trust_voided_check_no_clear BEFORE INSERT ON s_trust_clearings WHEN EXISTS(SELECT 1 FROM s_trust_checks k JOIN s_trust_entries e ON e.source_id=k.transaction_id JOIN s_trust_journal_reversals r ON r.original_entry_id=e.id LEFT JOIN s_trust_journal_decisions d ON d.reversal_id=r.id WHERE e.id=NEW.entry_id AND (d.id IS NULL OR d.decision='approved')) BEGIN SELECT RAISE(ABORT,'check void is pending or approved'); END;
CREATE TRIGGER s_trust_cleared_check_no_void BEFORE INSERT ON s_trust_journal_decisions WHEN NEW.decision='approved' AND EXISTS(SELECT 1 FROM s_trust_journal_reversals r JOIN s_trust_entries e ON e.id=r.original_entry_id JOIN s_trust_checks k ON k.transaction_id=e.source_id WHERE r.id=NEW.reversal_id AND (e.cleared_date IS NOT NULL OR EXISTS(SELECT 1 FROM s_trust_clearings c WHERE c.entry_id=e.id))) BEGIN SELECT RAISE(ABORT,'a cleared check requires a bank reversal'); END;

-- TIME-007: firm UTBMS code sets, LEDES timekeeper IDs, append-only client billing
-- guidelines, frozen LEDES 1998B invoices and imported e-billing outcomes.
CREATE TABLE s_utbms_codes (
 kind TEXT NOT NULL CHECK(kind IN('task','activity','expense')), code TEXT NOT NULL, label TEXT NOT NULL,
 active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), updated_by TEXT NOT NULL, updated_at TEXT NOT NULL,
