CREATE TABLE s_conflict_waiver_details(waiver_id TEXT PRIMARY KEY REFERENCES s_conflict_waivers(id),parties TEXT NOT NULL CHECK(json_valid(parties)),waiver_date TEXT NOT NULL,scope TEXT NOT NULL,match_id TEXT NOT NULL,confirmation TEXT NOT NULL,label TEXT NOT NULL CHECK(label='practitioner-recorded, not signed through Satchel'));
CREATE TABLE s_staff_relationships(id TEXT PRIMARY KEY,party_id TEXT NOT NULL REFERENCES s_parties(id),staff_email TEXT NOT NULL,kind TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT,source TEXT NOT NULL,actor TEXT NOT NULL,at TEXT NOT NULL);
CREATE TRIGGER s_staff_relationship_added AFTER INSERT ON s_staff_relationships BEGIN UPDATE s_meta SET party_revision=party_revision+1 WHERE id=1; END;
CREATE TABLE s_matter_exclusions(matter_id TEXT NOT NULL REFERENCES s_matters(id),email TEXT NOT NULL,restriction TEXT NOT NULL,recorded_by TEXT NOT NULL,at TEXT NOT NULL,released_by TEXT,released_at TEXT,release_reason TEXT,PRIMARY KEY(matter_id,email));
CREATE TRIGGER s_excluded_grant BEFORE INSERT ON s_matter_access WHEN EXISTS(SELECT 1 FROM s_matter_exclusions e WHERE e.matter_id=NEW.matter_id AND e.email=NEW.email AND e.released_at IS NULL) BEGIN SELECT RAISE(ABORT,'constraint: engagement restriction excludes staff'); END;
-- SAT-002's party-revision trigger is the atomic staleness fence. The application
-- also fences the latest counsel and every latest route decision in its batch.
DROP TRIGGER s_matter_conflict_disposition;
CREATE TRIGGER s_matter_conflict_disposition BEFORE INSERT ON s_matters WHEN (SELECT COALESCE(disposition,CASE decision WHEN 'declined' THEN 'decline' ELSE 'no_conflict' END) FROM s_conflict_reviews WHERE search_id=NEW.conflict_id ORDER BY sequence DESC LIMIT 1)='decline' BEGIN SELECT RAISE(ABORT,'stale conflict disposition'); END;
CREATE TRIGGER s_conflict_routes_update BEFORE UPDATE ON s_conflict_routes BEGIN SELECT RAISE(ABORT,'Conflict routes are immutable'); END;
CREATE TRIGGER s_conflict_routes_delete BEFORE DELETE ON s_conflict_routes BEGIN SELECT RAISE(ABORT,'Conflict routes are immutable'); END;
CREATE TRIGGER s_conflict_route_decisions_update BEFORE UPDATE ON s_conflict_route_decisions BEGIN SELECT RAISE(ABORT,'Conflict decisions are immutable'); END;
CREATE TRIGGER s_conflict_route_decisions_delete BEFORE DELETE ON s_conflict_route_decisions BEGIN SELECT RAISE(ABORT,'Conflict decisions are immutable'); END;
CREATE TRIGGER s_conflict_waiver_details_update BEFORE UPDATE ON s_conflict_waiver_details BEGIN SELECT RAISE(ABORT,'Waiver evidence is immutable'); END;
CREATE TRIGGER s_conflict_waiver_details_delete BEFORE DELETE ON s_conflict_waiver_details BEGIN SELECT RAISE(ABORT,'Waiver evidence is immutable'); END;
CREATE TRIGGER s_staff_relationships_update BEFORE UPDATE ON s_staff_relationships BEGIN SELECT RAISE(ABORT,'Staff relationships are immutable'); END;
CREATE TRIGGER s_staff_relationships_delete BEFORE DELETE ON s_staff_relationships BEGIN SELECT RAISE(ABORT,'Staff relationships are immutable'); END;

CREATE TRIGGER s_conflict_lead_insert AFTER INSERT ON s_leads BEGIN UPDATE s_meta SET party_revision=party_revision+1 WHERE id=1; END;
CREATE TRIGGER s_conflict_lead_update AFTER UPDATE ON s_leads BEGIN UPDATE s_meta SET party_revision=party_revision+1 WHERE id=1; END;
-- Counsel records the contact association; a public inquiry never claims an
-- existing identity or communication consent merely by supplying its name.
CREATE TABLE s_lead_contacts(lead_id TEXT NOT NULL REFERENCES s_leads(id),party_id TEXT NOT NULL REFERENCES s_parties(id),actor TEXT NOT NULL,at TEXT NOT NULL,PRIMARY KEY(lead_id,party_id));
CREATE TRIGGER s_lead_contact_added AFTER INSERT ON s_lead_contacts BEGIN UPDATE s_meta SET party_revision=party_revision+1 WHERE id=1; END;

CREATE TABLE s_conflict_waiver_matters(waiver_id TEXT NOT NULL REFERENCES s_conflict_waivers(id),matter_id TEXT NOT NULL REFERENCES s_matters(id),PRIMARY KEY(waiver_id,matter_id));
CREATE TABLE s_conflict_disposals(id TEXT PRIMARY KEY,waiver_id TEXT NOT NULL UNIQUE REFERENCES s_conflict_waivers(id),reason TEXT NOT NULL,journal TEXT NOT NULL,approved_by TEXT NOT NULL,approved_at TEXT NOT NULL);
-- Like document originals, only approved erasure may clear bytes; metadata stays.
DROP TRIGGER s_conflict_waiver_chunks_immutable_update;
CREATE TRIGGER s_conflict_waiver_chunks_immutable_update BEFORE UPDATE ON s_conflict_waiver_chunks WHEN NEW.waiver_id IS NOT OLD.waiver_id OR NEW.position IS NOT OLD.position OR NEW.content_base64<>'' OR NOT EXISTS(SELECT 1 FROM s_conflict_disposals d WHERE d.waiver_id=OLD.waiver_id) BEGIN SELECT RAISE(ABORT,'Original conflict waivers are immutable'); END;
DROP TRIGGER s_conflict_waiver_details_update;
CREATE TRIGGER s_conflict_waiver_details_update BEFORE UPDATE ON s_conflict_waiver_details WHEN NEW.waiver_id IS NOT OLD.waiver_id OR NEW.parties IS NOT OLD.parties OR NEW.waiver_date IS NOT OLD.waiver_date OR NEW.scope IS NOT OLD.scope OR NEW.match_id IS NOT OLD.match_id OR NEW.label IS NOT OLD.label OR NEW.confirmation<>'' OR NOT EXISTS(SELECT 1 FROM s_conflict_disposals d WHERE d.waiver_id=OLD.waiver_id) BEGIN SELECT RAISE(ABORT,'Waiver evidence is immutable'); END;
CREATE TRIGGER s_conflict_disposals_update BEFORE UPDATE ON s_conflict_disposals BEGIN SELECT RAISE(ABORT,'Conflict disposal is immutable'); END;
CREATE TRIGGER s_conflict_disposals_delete BEFORE DELETE ON s_conflict_disposals BEGIN SELECT RAISE(ABORT,'Conflict disposal is immutable'); END;

-- Multiple hidden matters with the same custodian expose one opaque route.
CREATE TABLE s_conflict_route_sources(search_id TEXT NOT NULL REFERENCES s_conflicts(id),route_id TEXT NOT NULL,wall_id TEXT NOT NULL REFERENCES s_ethical_walls(id),PRIMARY KEY(search_id,wall_id));
CREATE TRIGGER s_conflict_route_sources_update BEFORE UPDATE ON s_conflict_route_sources BEGIN SELECT RAISE(ABORT,'Route sources are immutable'); END;
CREATE TRIGGER s_conflict_route_sources_delete BEFORE DELETE ON s_conflict_route_sources BEGIN SELECT RAISE(ABORT,'Route sources are immutable'); END;

-- Original payloads may be redacted only behind an approved retained-original
-- journal. Record keys, decisions, attribution, hashes and exclusion enforcement
-- remain. No erasure can grant access or clear an engagement.
CREATE TABLE s_conflict_policy_disposals(search_id TEXT PRIMARY KEY REFERENCES s_conflicts(id),reason TEXT NOT NULL,journal TEXT NOT NULL,approved_by TEXT NOT NULL,approved_at TEXT NOT NULL);
CREATE TABLE s_conflict_policy_audit_redactions(audit_id TEXT PRIMARY KEY REFERENCES s_audit(id),search_id TEXT NOT NULL REFERENCES s_conflict_policy_disposals(search_id),sha256 TEXT NOT NULL,redacted_detail TEXT NOT NULL,redacted_evidence TEXT NOT NULL);
DROP TRIGGER s_conflict_reviews_immutable_update;
CREATE TRIGGER s_conflict_reviews_immutable_update BEFORE UPDATE ON s_conflict_reviews WHEN NEW.id IS NOT OLD.id OR NEW.search_id IS NOT OLD.search_id OR NEW.actor IS NOT OLD.actor OR NEW.decision IS NOT OLD.decision OR NEW.waiver_id IS NOT OLD.waiver_id OR NEW.created_at IS NOT OLD.created_at OR NEW.sequence IS NOT OLD.sequence OR NEW.disposition IS NOT OLD.disposition OR NEW.excluded_staff IS NOT OLD.excluded_staff OR NEW.screen_custodian IS NOT OLD.screen_custodian OR NEW.restrictions<>'["Disposed conflict payload; consult counsel"]' OR NOT (EXISTS(SELECT 1 FROM s_conflict_policy_disposals d WHERE d.search_id=OLD.search_id)) OR NEW.note<>'Disposed conflict payload; consult counsel' BEGIN SELECT RAISE(ABORT,'Conflict evidence is immutable outside approved payload disposal'); END;
DROP TRIGGER s_conflict_route_decisions_update;
CREATE TRIGGER s_conflict_route_decisions_update BEFORE UPDATE ON s_conflict_route_decisions WHEN NEW.id IS NOT OLD.id OR NEW.referral_id IS NOT OLD.referral_id OR NEW.revision IS NOT OLD.revision OR NEW.decision IS NOT OLD.decision OR NEW.excluded_staff IS NOT OLD.excluded_staff OR NEW.screen_custodian IS NOT OLD.screen_custodian OR NEW.waiver_id IS NOT OLD.waiver_id OR NEW.actor IS NOT OLD.actor OR NEW.created_at IS NOT OLD.created_at OR NEW.sequence IS NOT OLD.sequence OR NEW.restrictions<>'["Disposed conflict payload; consult counsel"]' OR NOT (EXISTS(SELECT 1 FROM s_conflict_policy_disposals d JOIN s_conflict_routes r ON r.search_id=d.search_id WHERE r.id=OLD.referral_id)) OR NEW.note<>'Disposed conflict payload; consult counsel' BEGIN SELECT RAISE(ABORT,'Conflict evidence is immutable outside approved payload disposal'); END;
DROP TRIGGER s_conflict_referral_decisions_immutable_update;
CREATE TRIGGER s_conflict_referral_decisions_immutable_update BEFORE UPDATE ON s_conflict_referral_decisions WHEN NEW.id IS NOT OLD.id OR NEW.referral_id IS NOT OLD.referral_id OR NEW.wall_revision IS NOT OLD.wall_revision OR NEW.decision IS NOT OLD.decision OR NEW.waiver_id IS NOT OLD.waiver_id OR NEW.actor IS NOT OLD.actor OR NEW.created_at IS NOT OLD.created_at OR NEW.sequence IS NOT OLD.sequence OR NEW.restrictions<>'["Disposed conflict payload; consult counsel"]' OR NOT (EXISTS(SELECT 1 FROM s_conflict_policy_disposals d JOIN s_conflict_referrals r ON r.search_id=d.search_id WHERE r.id=OLD.referral_id)) OR NEW.note<>'Disposed conflict payload; consult counsel' BEGIN SELECT RAISE(ABORT,'Conflict evidence is immutable outside approved payload disposal'); END;
DROP TRIGGER s_matter_conflict_terms_immutable_update;
CREATE TRIGGER s_matter_conflict_terms_immutable_update BEFORE UPDATE ON s_matter_conflict_terms WHEN NEW.matter_id IS NOT OLD.matter_id OR NEW.review_id IS NOT OLD.review_id OR NEW.acknowledged_by IS NOT OLD.acknowledged_by OR NEW.at IS NOT OLD.at OR NEW.restrictions<>'["Disposed conflict payload; consult counsel"]' OR NOT (EXISTS(SELECT 1 FROM s_conflict_policy_disposals d JOIN s_matters m ON m.conflict_id=d.search_id WHERE m.id=OLD.matter_id)) BEGIN SELECT RAISE(ABORT,'Conflict evidence is immutable outside approved payload disposal'); END;
DROP TRIGGER s_audit_no_update;
CREATE TRIGGER s_audit_no_update BEFORE UPDATE ON s_audit WHEN NEW.id IS NOT OLD.id OR NEW.actor IS NOT OLD.actor OR NEW.action IS NOT OLD.action OR NEW.object_id IS NOT OLD.object_id OR NEW.at IS NOT OLD.at OR NEW.actor_id IS NOT OLD.actor_id OR NEW.role IS NOT OLD.role OR NEW.channel IS NOT OLD.channel OR NEW.matter_id IS NOT OLD.matter_id OR NEW.revision IS NOT OLD.revision OR NOT EXISTS(SELECT 1 FROM s_conflict_policy_audit_redactions r WHERE r.audit_id=OLD.id AND NEW.detail=r.redacted_detail AND NEW.evidence=r.redacted_evidence) BEGIN SELECT RAISE(ABORT,'action audit is append-only outside approved original-payload disposal'); END;
CREATE TRIGGER s_conflict_policy_disposals_update BEFORE UPDATE ON s_conflict_policy_disposals BEGIN SELECT RAISE(ABORT,'Conflict disposal journal is immutable'); END;
CREATE TRIGGER s_conflict_policy_disposals_delete BEFORE DELETE ON s_conflict_policy_disposals BEGIN SELECT RAISE(ABORT,'Conflict disposal journal is immutable'); END;
CREATE TRIGGER s_conflict_policy_audit_redactions_update BEFORE UPDATE ON s_conflict_policy_audit_redactions BEGIN SELECT RAISE(ABORT,'Conflict disposal journal is immutable'); END;
CREATE TRIGGER s_conflict_policy_audit_redactions_delete BEFORE DELETE ON s_conflict_policy_audit_redactions BEGIN SELECT RAISE(ABORT,'Conflict disposal journal is immutable'); END;
CREATE TABLE s_conflict_retention_scopes(search_id TEXT NOT NULL REFERENCES s_conflicts(id),matter_id TEXT NOT NULL REFERENCES s_matters(id),PRIMARY KEY(search_id,matter_id));
CREATE TRIGGER s_conflict_retention_scopes_update BEFORE UPDATE ON s_conflict_retention_scopes BEGIN SELECT RAISE(ABORT,'Conflict custody is immutable'); END;
CREATE TRIGGER s_conflict_retention_scopes_delete BEFORE DELETE ON s_conflict_retention_scopes BEGIN SELECT RAISE(ABORT,'Conflict custody is immutable'); END;

-- FIRM-002: finance/billing, accountant and client member roles; explicit client portal grants.
DROP TRIGGER s_deadline_superseded_audit;
CREATE TABLE s_members_new(email TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('lawyer','assistant','trust_officer','billing','accountant','client')), active INTEGER NOT NULL DEFAULT 1);
INSERT INTO s_members_new SELECT email,name,role,active FROM s_members;
DROP TABLE s_members;
ALTER TABLE s_members_new RENAME TO s_members;
CREATE TRIGGER s_deadline_superseded_audit AFTER UPDATE OF status ON s_deadlines WHEN NEW.status='superseded' AND OLD.status<>'superseded' BEGIN
 INSERT INTO s_audit(id,actor,action,object_id,detail,at,actor_id,role,channel,matter_id,revision,evidence)
 SELECT lower(hex(randomblob(16))),d.updated_by,'deadline.source_superseded',NEW.id,json_object('previousStatus',OLD.status,'replacementVersion',d.current_version,'erasedAt',d.erased_at),d.updated_at,o.id,CASE WHEN o.role='owner' THEN 'owner' ELSE m.role END,d.updated_channel,NEW.matter_id,NEW.revision,json_object('record',json_object('recordType','s_deadlines','id',NEW.id,'matterId',NEW.matter_id,'revision',NEW.revision,'source',NEW.source,'documentId',NEW.document_id,'reviewedDocumentVersion',NEW.document_version,'status',NEW.status)) FROM s_documents d JOIN oa_operators o ON o.email=d.updated_by LEFT JOIN s_members m ON m.email=o.email WHERE d.id=NEW.document_id;
END;
CREATE TABLE s_portal_grants(id TEXT PRIMARY KEY,email TEXT NOT NULL,matter_id TEXT NOT NULL REFERENCES s_matters(id),granted_by TEXT NOT NULL,granted_at TEXT NOT NULL,reason TEXT NOT NULL,revoked_by TEXT,revoked_at TEXT,revoke_reason TEXT);
CREATE UNIQUE INDEX s_portal_grants_active ON s_portal_grants(email,matter_id) WHERE revoked_at IS NULL;
CREATE TRIGGER s_portal_grants_no_delete BEFORE DELETE ON s_portal_grants BEGIN SELECT RAISE(ABORT,'portal grants are history'); END;
CREATE TRIGGER s_portal_grants_revoke_only BEFORE UPDATE ON s_portal_grants WHEN NEW.id IS NOT OLD.id OR NEW.email IS NOT OLD.email OR NEW.matter_id IS NOT OLD.matter_id OR NEW.granted_by IS NOT OLD.granted_by OR NEW.granted_at IS NOT OLD.granted_at OR NEW.reason IS NOT OLD.reason OR OLD.revoked_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'portal grants are history'); END;

-- FIRM-008: principal-defined custom roles. Each role is a ceiling of per-area permissions
-- applied to a firm member on top of their built-in role; it never confers legal approval or trust authority.
CREATE TABLE s_custom_roles(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,permissions TEXT NOT NULL CHECK(json_valid(permissions)),revision INTEGER NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL);
ALTER TABLE s_members ADD COLUMN custom_role_id TEXT REFERENCES s_custom_roles(id);

-- OSS-001: the principal's recorded review of a provider's own terms and direct firm billing before Satchel connects it.
CREATE TABLE s_provider_reviews(id TEXT PRIMARY KEY,provider_id TEXT NOT NULL,terms_url TEXT NOT NULL,disclosure_version INTEGER NOT NULL,reviewed_by TEXT NOT NULL,reviewed_at TEXT NOT NULL);
CREATE INDEX s_provider_reviews_provider ON s_provider_reviews(provider_id,reviewed_at);

-- INTAKE-008: consented, bounded follow-up sequences. A message is sent only while the lead's own recorded consent
-- is active (a contact merge supplies none), inside quiet-hour and contact limits, and until a reply, opt-out,
-- conflict stop, decline or conversion stops it and names the next human action.
CREATE TABLE s_followup_settings(kind TEXT PRIMARY KEY CHECK(kind IN('consultation_reminder','unanswered_inquiry','engagement_chase')),enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),channel TEXT NOT NULL CHECK(channel='email'),steps TEXT NOT NULL CHECK(json_valid(steps)),quiet_start TEXT NOT NULL,quiet_end TEXT NOT NULL,timezone TEXT NOT NULL,max_contacts INTEGER NOT NULL CHECK(max_contacts BETWEEN 1 AND 20),revision TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE s_lead_consents(id TEXT PRIMARY KEY,lead_id TEXT NOT NULL REFERENCES s_leads(id),channel TEXT NOT NULL CHECK(channel='email'),source TEXT NOT NULL,text TEXT NOT NULL,recorded_by TEXT NOT NULL,granted_at TEXT NOT NULL,revoked_at TEXT,revoked_reason TEXT);
CREATE UNIQUE INDEX s_lead_consent_active ON s_lead_consents(lead_id,channel) WHERE revoked_at IS NULL;
CREATE TABLE s_followups(id TEXT PRIMARY KEY,lead_id TEXT NOT NULL REFERENCES s_leads(id),kind TEXT NOT NULL CHECK(kind IN('consultation_reminder','unanswered_inquiry','engagement_chase')),status TEXT NOT NULL CHECK(status IN('active','completed','stopped')),anchor_at TEXT NOT NULL,context TEXT NOT NULL CHECK(json_valid(context)),stop_reason TEXT,stopped_at TEXT,next_action TEXT,human_owner TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX s_followups_lead ON s_followups(lead_id,status);
CREATE TABLE s_followup_sends(id TEXT PRIMARY KEY,followup_id TEXT NOT NULL REFERENCES s_followups(id),step INTEGER NOT NULL,due_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('queued','sending','sent','failed','uncertain','cancelled')),claim TEXT,provider TEXT,provider_id TEXT,detail TEXT NOT NULL DEFAULT '',attempted_at TEXT,UNIQUE(followup_id,step));
CREATE INDEX s_followup_sends_due ON s_followup_sends(status,due_at);

-- INTAKE-003: approved consultation availability, atomic bookings, one linked lead and intake record per booking.
CREATE TABLE s_consult_offers(id TEXT PRIMARY KEY,title TEXT NOT NULL,lawyer_email TEXT NOT NULL,timezone TEXT NOT NULL,duration_minutes INTEGER NOT NULL CHECK(duration_minutes BETWEEN 10 AND 240),buffer_before INTEGER NOT NULL CHECK(buffer_before BETWEEN 0 AND 120),buffer_after INTEGER NOT NULL CHECK(buffer_after BETWEEN 0 AND 120),windows TEXT NOT NULL CHECK(json_valid(windows)),notice_hours INTEGER NOT NULL CHECK(notice_hours BETWEEN 0 AND 720),horizon_days INTEGER NOT NULL CHECK(horizon_days BETWEEN 1 AND 90),fee_cents INTEGER NOT NULL CHECK(fee_cents>=0),form_id TEXT REFERENCES s_intake_forms(id),consent_text TEXT NOT NULL,published INTEGER NOT NULL CHECK(published IN(0,1)),revision TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE s_consultations(id TEXT PRIMARY KEY,offer_id TEXT NOT NULL REFERENCES s_consult_offers(id),lead_id TEXT NOT NULL REFERENCES s_leads(id),lawyer_email TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,busy_start TEXT NOT NULL,busy_end TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('booked','cancelled')),prospect_timezone TEXT NOT NULL,manage_hash TEXT NOT NULL UNIQUE,fee_cents INTEGER NOT NULL,fee_status TEXT NOT NULL CHECK(fee_status IN('none','due_at_consultation')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX s_consultations_lawyer ON s_consultations(lawyer_email,status,busy_start);
CREATE TABLE s_consult_events(id TEXT PRIMARY KEY,consultation_id TEXT NOT NULL REFERENCES s_consultations(id),kind TEXT NOT NULL,detail TEXT NOT NULL CHECK(json_valid(detail)),actor TEXT NOT NULL,at TEXT NOT NULL);
CREATE TRIGGER s_consult_event_update BEFORE UPDATE ON s_consult_events BEGIN SELECT RAISE(ABORT,'constraint: consultation history is append-only'); END;
CREATE TRIGGER s_consult_event_delete BEFORE DELETE ON s_consult_events BEGIN SELECT RAISE(ABORT,'constraint: consultation history is append-only'); END;
CREATE TABLE s_consult_rate_limits(ip_digest TEXT NOT NULL,hour TEXT NOT NULL,accepted INTEGER NOT NULL CHECK(accepted BETWEEN 0 AND 10),expires_at TEXT NOT NULL,PRIMARY KEY(ip_digest,hour));

-- MATTER-005: matter notes, calls and client commitments. A private note is visible to its author alone; a team note
-- to everyone who sees the matter; a client-visible entry (always a team entry) appears in that matter's client timeline.
-- Entries are append-only: a correction is a new entry that cites the old one.
CREATE TABLE s_matter_notes(id TEXT PRIMARY KEY,matter_id TEXT NOT NULL REFERENCES s_matters(id),kind TEXT NOT NULL CHECK(kind IN('note','call','commitment')),title TEXT NOT NULL,body TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('private','team')),client_visible INTEGER NOT NULL CHECK(client_visible IN(0,1)),occurred_at TEXT NOT NULL,mentions TEXT NOT NULL CHECK(json_valid(mentions)),corrects TEXT REFERENCES s_matter_notes(id),author_email TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(visibility='team' OR client_visible=0),CHECK(visibility='team' OR mentions='[]'));
CREATE INDEX s_matter_notes_matter ON s_matter_notes(matter_id,occurred_at);
CREATE TRIGGER s_matter_note_update BEFORE UPDATE ON s_matter_notes BEGIN SELECT RAISE(ABORT,'constraint: matter notes are append-only'); END;
CREATE TRIGGER s_matter_note_delete BEFORE DELETE ON s_matter_notes BEGIN SELECT RAISE(ABORT,'constraint: matter notes are append-only'); END;

-- CLIENT-004 / CLIENT-001: a lawyer expressly shares one task, event, confirmed deadline or document with the clients who hold portal grants.
-- The client may acknowledge any of them and mark a shared client task done; neither changes the firm's own record.
CREATE TABLE s_client_shares(id TEXT PRIMARY KEY,matter_id TEXT NOT NULL REFERENCES s_matters(id),kind TEXT NOT NULL CHECK(kind IN('task','event','deadline','document')),record_id TEXT NOT NULL,instructions TEXT NOT NULL,shared_by TEXT NOT NULL,shared_at TEXT NOT NULL,revoked_by TEXT,revoked_at TEXT);
CREATE UNIQUE INDEX s_client_share_open ON s_client_shares(kind,record_id) WHERE revoked_at IS NULL;
CREATE TABLE s_client_acks(id TEXT PRIMARY KEY,share_id TEXT NOT NULL REFERENCES s_client_shares(id),kind TEXT NOT NULL CHECK(kind IN('acknowledged','completed')),client_email TEXT NOT NULL,note TEXT NOT NULL,at TEXT NOT NULL);
CREATE UNIQUE INDEX s_client_ack_once ON s_client_acks(share_id,client_email,kind);
CREATE TRIGGER s_client_ack_update BEFORE UPDATE ON s_client_acks BEGIN SELECT RAISE(ABORT,'constraint: client acknowledgments are append-only'); END;
CREATE TRIGGER s_client_ack_delete BEFORE DELETE ON s_client_acks BEGIN SELECT RAISE(ABORT,'constraint: client acknowledgments are append-only'); END;

-- CLIENT-001: a portal grant names what kind of person holds it. A client and a co-client each read what is shared; a
-- payer reads only issued invoices; a delegate acts for one named client and loses access when that client's grant or
-- their own is withdrawn.
ALTER TABLE s_portal_grants ADD COLUMN kind TEXT NOT NULL DEFAULT 'client' CHECK(kind IN('client','co_client','payer','delegate'));
ALTER TABLE s_portal_grants ADD COLUMN delegate_of TEXT;
DROP TRIGGER s_portal_grants_revoke_only;
CREATE TRIGGER s_portal_grants_revoke_only BEFORE UPDATE ON s_portal_grants WHEN NEW.id IS NOT OLD.id OR NEW.email IS NOT OLD.email OR NEW.matter_id IS NOT OLD.matter_id OR NEW.granted_by IS NOT OLD.granted_by OR NEW.granted_at IS NOT OLD.granted_at OR NEW.reason IS NOT OLD.reason OR NEW.kind IS NOT OLD.kind OR NEW.delegate_of IS NOT OLD.delegate_of OR OLD.revoked_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'portal grants are history'); END;

-- CLIENT-002: retained two-way portal threads. A thread belongs to one matter; its participants are the matter's portal
-- readers (client, co-client, delegate) and the staff assigned to it. Messages and attachments are append-only. Read
-- state is per reader; a notification email carries no message content and its provider outcome is recorded.
CREATE TABLE s_portal_threads(id TEXT PRIMARY KEY,matter_id TEXT NOT NULL REFERENCES s_matters(id),subject TEXT NOT NULL,assigned_to TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX s_portal_threads_matter ON s_portal_threads(matter_id,created_at);
CREATE TABLE s_portal_messages(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES s_portal_threads(id),sender_email TEXT NOT NULL,sender_side TEXT NOT NULL CHECK(sender_side IN('staff','client')),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX s_portal_messages_thread ON s_portal_messages(thread_id,created_at);
CREATE TABLE s_portal_attachments(id TEXT PRIMARY KEY,message_id TEXT NOT NULL REFERENCES s_portal_messages(id),name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,content_base64 TEXT NOT NULL);
CREATE TABLE s_portal_reads(message_id TEXT NOT NULL REFERENCES s_portal_messages(id),reader_email TEXT NOT NULL,read_at TEXT NOT NULL,PRIMARY KEY(message_id,reader_email));
CREATE TABLE s_portal_notifications(id TEXT PRIMARY KEY,message_id TEXT NOT NULL REFERENCES s_portal_messages(id),recipient TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('accepted','failed','uncertain','not_sent')),provider TEXT,provider_id TEXT,detail TEXT NOT NULL,at TEXT NOT NULL);
CREATE TRIGGER s_portal_message_update BEFORE UPDATE ON s_portal_messages BEGIN SELECT RAISE(ABORT,'constraint: portal messages are append-only'); END;
CREATE TRIGGER s_portal_message_delete BEFORE DELETE ON s_portal_messages BEGIN SELECT RAISE(ABORT,'constraint: portal messages are append-only'); END;
CREATE TRIGGER s_portal_attachment_update BEFORE UPDATE ON s_portal_attachments BEGIN SELECT RAISE(ABORT,'constraint: portal attachments are append-only'); END;
CREATE TRIGGER s_portal_attachment_delete BEFORE DELETE ON s_portal_attachments BEGIN SELECT RAISE(ABORT,'constraint: portal attachments are append-only'); END;

-- CLIENT-003: a document request can carry the firm's instructions, owner and acceptance criteria, be shared with the
-- matter's portal readers, receive uploads, and be closed only by counsel accepting one upload as the retained original.
ALTER TABLE s_document_requests ADD COLUMN instructions TEXT NOT NULL DEFAULT '';
ALTER TABLE s_document_requests ADD COLUMN owner_email TEXT;
ALTER TABLE s_document_requests ADD COLUMN criteria TEXT NOT NULL DEFAULT '';
ALTER TABLE s_document_requests ADD COLUMN client_visible INTEGER NOT NULL DEFAULT 0 CHECK(client_visible IN(0,1));
CREATE TABLE s_request_uploads(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES s_document_requests(id),uploader_email TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,content_base64 TEXT NOT NULL,uploaded_at TEXT NOT NULL,review TEXT NOT NULL DEFAULT 'submitted' CHECK(review IN('submitted','accepted','deficient')),reviewed_by TEXT,reviewed_at TEXT,review_note TEXT,document_id TEXT REFERENCES s_documents(id));
CREATE INDEX s_request_uploads_request ON s_request_uploads(request_id,uploaded_at);
CREATE TRIGGER s_request_upload_once BEFORE UPDATE ON s_request_uploads WHEN OLD.review<>'submitted' OR NEW.request_id IS NOT OLD.request_id OR NEW.uploader_email IS NOT OLD.uploader_email OR NEW.name IS NOT OLD.name OR NEW.sha256 IS NOT OLD.sha256 OR NEW.content_base64 IS NOT OLD.content_base64 OR NEW.uploaded_at IS NOT OLD.uploaded_at BEGIN SELECT RAISE(ABORT,'constraint: an uploaded original is final and reviewed once'); END;
CREATE TRIGGER s_request_upload_delete BEFORE DELETE ON s_request_uploads BEGIN SELECT RAISE(ABORT,'constraint: uploads are history'); END;
CREATE TABLE s_request_notes(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES s_document_requests(id),upload_id TEXT REFERENCES s_request_uploads(id),side TEXT NOT NULL CHECK(side IN('staff','client')),author_email TEXT NOT NULL,body TEXT NOT NULL,at TEXT NOT NULL);
CREATE TRIGGER s_request_note_update BEFORE UPDATE ON s_request_notes BEGIN SELECT RAISE(ABORT,'constraint: request notes are append-only'); END;
CREATE TRIGGER s_request_note_delete BEFORE DELETE ON s_request_notes BEGIN SELECT RAISE(ABORT,'constraint: request notes are append-only'); END;

-- REPORT-003: saved report definitions with weekly permissioned summaries. A delivery is one recipient for one scheduled
-- slot; revoking a recipient removes them from every later slot, and a failed delivery opens an exception with a due owner.
CREATE TABLE s_report_schedules(id TEXT PRIMARY KEY,name TEXT NOT NULL,dashboard TEXT NOT NULL CHECK(dashboard IN('workload','deadlines')),filters TEXT NOT NULL CHECK(json_valid(filters)),weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7),time TEXT NOT NULL,timezone TEXT NOT NULL,channel TEXT NOT NULL CHECK(channel IN('email','portal')),recipients TEXT NOT NULL CHECK(json_valid(recipients)),owner_email TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)),revision TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE s_report_deliveries(id TEXT PRIMARY KEY,schedule_id TEXT NOT NULL REFERENCES s_report_schedules(id),slot TEXT NOT NULL,recipient TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('queued','accepted','available','failed','uncertain','skipped')),summary TEXT,provider TEXT,provider_id TEXT,detail TEXT NOT NULL DEFAULT '',at TEXT NOT NULL,UNIQUE(schedule_id,slot,recipient));
CREATE TABLE s_report_exceptions(id TEXT PRIMARY KEY,schedule_id TEXT NOT NULL REFERENCES s_report_schedules(id),delivery_id TEXT NOT NULL REFERENCES s_report_deliveries(id),recipient TEXT NOT NULL,owner_email TEXT NOT NULL,due_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('open','resolved')),note TEXT,created_at TEXT NOT NULL,resolved_by TEXT,resolved_at TEXT);
CREATE TRIGGER s_report_delivery_delete BEFORE DELETE ON s_report_deliveries BEGIN SELECT RAISE(ABORT,'constraint: report deliveries are history'); END;
CREATE TRIGGER s_report_exception_delete BEFORE DELETE ON s_report_exceptions BEGIN SELECT RAISE(ABORT,'constraint: report exceptions are history'); END;

ALTER TABLE rer_dependency_installation ADD COLUMN keys_sealed INTEGER NOT NULL DEFAULT 0 CHECK(keys_sealed IN (0,1));
-- Nonsecret version history lets restored rows name an unavailable retired key
-- without confusing ciphertext tampering or a wrong current secret with restore.
ALTER TABLE rer_dependency_installation ADD COLUMN key_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(key_ids) AND json_type(key_ids)='array');

-- Counsel-reviewed, immutable internal production packets.
CREATE TABLE s_document_productions (
 id TEXT PRIMARY KEY, matter_id TEXT NOT NULL REFERENCES s_matters(id),
 snapshot TEXT, artifact_base64 TEXT, sha256 TEXT NOT NULL, size INTEGER NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('draft','approved','recalled','erased')),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 approved_by TEXT, approved_at TEXT, review_note TEXT, review_note_sha256 TEXT,
 exported_at TEXT, recalled_by TEXT, recalled_at TEXT, recall_reason TEXT, recall_reason_sha256 TEXT
);
CREATE TABLE s_production_sources (
 production_id TEXT NOT NULL REFERENCES s_document_productions(id),
 document_id TEXT NOT NULL, version INTEGER NOT NULL,
 PRIMARY KEY(production_id,document_id),
 FOREIGN KEY(document_id,version) REFERENCES s_document_versions(document_id,version)
);
CREATE INDEX s_production_matter ON s_document_productions(matter_id);

-- Never reuse an issued Bates label within a matter, including recalled packets.
CREATE TABLE s_production_bates (
 matter_id TEXT NOT NULL REFERENCES s_matters(id), label TEXT NOT NULL,
 production_id TEXT NOT NULL REFERENCES s_document_productions(id),
 PRIMARY KEY(matter_id,label)
);

-- Native health-data setup and counsel-reviewed source-page chronologies.
CREATE TABLE s_health_setup (
 matter_id TEXT PRIMARY KEY REFERENCES s_matters(id), authorization_reference TEXT NOT NULL,
 agreement_reference TEXT NOT NULL, reviewed_by TEXT NOT NULL, reviewed_at TEXT NOT NULL
);
CREATE TABLE s_document_chronologies (
 id TEXT PRIMARY KEY, matter_id TEXT NOT NULL REFERENCES s_matters(id),
 snapshot TEXT, sha256 TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','published','erased')),
 review TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, published_by TEXT, published_at TEXT
);
CREATE TABLE s_chronology_sources (
 chronology_id TEXT NOT NULL REFERENCES s_document_chronologies(id),
 document_id TEXT NOT NULL, version INTEGER NOT NULL,
 PRIMARY KEY(chronology_id,document_id,version),
 FOREIGN KEY(document_id,version) REFERENCES s_document_versions(document_id,version)
);
